<div class="page-head"><div><h1 class="h2">Magazzino</h1><p class="text-secondary mb-0">Giacenze, lotti, scadenze e prodotti usati negli interventi.</p></div><a class="btn btn-primary" href="/app/magazzino/nuovo">＋ Aggiungi prodotto</a></div>
<?php if(!$prodotti): ?><div class="card border-0 shadow-sm"><div class="empty-state"><strong>Magazzino vuoto</strong><p class="mb-3 mt-1">Registra i prodotti per iniziare a tracciare scorte e movimenti.</p><a class="btn btn-primary" href="/app/magazzino/nuovo">Aggiungi il primo prodotto</a></div></div><?php else: ?><div class="filters"><label class="visually-hidden" for="stockSearch">Cerca prodotti</label><input class="form-control" type="search" id="stockSearch" placeholder="Nome, codice o categoria" data-live-filter="#stockRows"></div><div class="table-wrap"><table class="table table-hover align-middle"><thead><tr><th>Prodotto</th><th>Codice</th><th>Categoria</th><th>Disponibile</th><th>Scorta minima</th><th>Stato scorta</th><th></th></tr></thead><tbody id="stockRows"><?php foreach($prodotti as $p):$low=(float)$p['giacenza']<=(float)$p['scorta_minima']; ?><tr><td class="fw-semibold"><?= e($p['nome']) ?></td><td><?= e($p['codice']?:'—') ?></td><td><?= e(ucfirst($p['categoria'])) ?></td><td><?= e($p['giacenza'].' '.$p['unita_misura']) ?></td><td><?= e($p['scorta_minima'].' '.$p['unita_misura']) ?></td><td><span class="badge rounded-pill <?= $low?'text-bg-warning':'text-bg-success' ?>"><?= $low?'Scorta bassa':'Disponibile' ?></span></td><td><a class="btn btn-sm btn-outline-primary" href="/app/magazzino/<?= (int)$p['id'] ?>">Scheda e movimenti</a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
